<script setup>
import {ref,computed,onMounted} from 'vue'
import Icon from '../Icon.vue'
import {request,upload} from './client'
import './student-count.css'
const data=ref(null),busy=ref(false),error=ref(''),notice=ref(''),selected=ref(null),file=ref(null),reference=ref('')
const month=ref(new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Colombo'}).slice(0,7))
const money=n=>new Intl.NumberFormat('en-LK',{style:'currency',currency:'LKR'}).format((n||0)/100)
const bankReady=computed(()=>['bank_name','account_name','account_number','branch'].every(k=>data.value?.bank?.[k]))
async function run(fn){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
async function load(){data.value=await request('student_count','summary',{month:month.value},'GET')}
async function issue(){await run(async()=>{const r=await request('student_count','issue',{month:month.value});notice.value=r.name?'Monthly bill is ready.':'No charge is due for this month.';await load()})}
function choose(row){selected.value=row;file.value=null;reference.value='';error.value=''}
function picked(event){file.value=event.target.files?.[0]||null;if(file.value?.size>5*1024*1024){file.value=null;error.value='Choose a receipt smaller than 5 MB.'}}
async function submit(){await run(async()=>{if(!file.value)throw Error('Choose your bank receipt.');const body=new FormData();body.append('file',file.value);const proof=await upload('commercial','upload_proof',body);await request('student_count','submit',{invoice:selected.value.name,proof:proof.name,reference:reference.value});selected.value=null;notice.value='Receipt submitted. SISU will check the bank transfer before marking this bill paid.';await load()})}
onMounted(()=>run(load))
</script>
<template><section class="student-count-space count-fees"><header class="count-heading"><div><h2>Monthly student-count fee</h2><p>Payable to SISU, separately from student tuition and your subscription.</p></div><Icon name="Users" :size="28"/></header><p v-if="error" role="alert" class="count-error">{{error}}</p><p v-if="notice" role="status" class="count-notice">{{notice}}</p>
<form class="count-filters" @submit.prevent="run(load)"><label>Billing month<input type="month" v-model="month" required></label><button class="button subtle" :disabled="busy">{{busy?'Loading…':'View month'}}</button></form>
<template v-if="data"><div class="count-fee-grid"><div><div class="count-equation"><div><strong>{{data.quantity}}</strong><span>qualifying students</span></div><span aria-hidden="true">×</span><div><strong>{{money(data.unit_minor)}}</strong><span>per student</span></div><span aria-hidden="true">=</span><div><strong>{{money(data.amount_minor)}}</strong><span>{{data.final?'Monthly total':'Current estimate'}}</span></div></div><p class="count-help">A student counts once after attending at least two different sessions in a calendar month, across all your classes. The final count is saved after the month ends.</p><p v-if="!data.enabled" class="count-help">Student-count billing is not enabled for this month.</p><button v-if="data.final&&data.enabled&&data.amount_minor&&!data.invoices.some(i=>i.month===month)" class="button primary" :disabled="busy" @click="issue">Prepare monthly bill</button></div>
<aside class="count-bank"><h3><Icon name="Building2" :size="20"/> SISU bank details</h3><dl v-if="bankReady"><dt>Account holder</dt><dd>{{data.bank.account_name}}</dd><dt>Account number</dt><dd class="count-account-number">{{data.bank.account_number}}</dd><dt>Bank & branch</dt><dd>{{data.bank.bank_name}} · {{data.bank.branch}}</dd></dl><p v-else>Bank details have not been configured. Please contact SISU before transferring money.</p><small>For student-count fees only. Student tuition is paid to the teacher or institute separately.</small></aside></div>
<h3 class="count-history-title">Student-count bills</h3><div class="count-table" v-if="data.invoices.length"><table><thead><tr><th>Month</th><th>Students × rate</th><th>Total</th><th>Status</th><th>Payment</th></tr></thead><tbody><tr v-for="i in data.invoices" :key="i.name"><td><strong>{{i.month}}</strong><small>{{i.name}}</small></td><td>{{i.quantity}} × {{money(i.unit_minor)}}</td><td><strong>{{money(i.amount_minor)}}</strong></td><td><span class="count-status" :class="i.status.toLowerCase()">{{i.status==='Pending'?'Under review':i.status}}</span><small v-if="i.review_note">{{i.review_note}}</small></td><td><button v-if="['Unpaid','Rejected'].includes(i.status)" class="button subtle" :disabled="busy||!bankReady" @click="choose(i)">Upload bank receipt</button><span v-else>{{i.status==='Paid'?'Payment approved':'Waiting for SISU review'}}</span></td></tr></tbody></table></div><div v-else class="count-empty"><h3>No monthly bills yet</h3><p>Your current month stays an estimate until the month ends.</p></div>
<form v-if="selected" class="count-receipt-form" @submit.prevent="submit"><div class="count-heading"><div><h3>Submit payment receipt</h3><p>{{selected.month}} · {{money(selected.amount_minor)}}</p></div><button type="button" class="button subtle" :disabled="busy" @click="selected=null">Cancel</button></div><label>Bank transfer reference<input v-model="reference" minlength="3" maxlength="140" required></label><label>Bank receipt<input type="file" accept=".pdf,.png,.jpg,.jpeg,.doc,.docx,.txt" @change="picked" required><small>PDF, image, Word or text · maximum 5 MB</small></label><button class="button primary" :disabled="busy||!file||!bankReady">{{busy?'Submitting…':'Send receipt for review'}}</button></form></template></section></template>
